using Godot;
using System;
using System.Linq;
using System.Threading.Tasks;
public partial class MigrationScene {
 async Task HabitatChecks(){var w=game.World;MigrationChecks.Assert(w.SpawnHeat(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ)==0,"Trailhead heat unsafe");MigrationChecks.Assert(w.RouteX(ExpeditionWorld.SpawnZ)>900&&w.RouteX(-700)<200,"Route is not southeast to northwest");MigrationChecks.Assert(Math.Abs(w.RouteX(-700)-w.LegacyRouteX(-700))<.001,"Existing northern map route moved");double forest=w.SpawnHeat(w.RouteX(-700)+100,-700),city=w.SpawnHeat(w.RouteX(-2100)+80,-2100);MigrationChecks.Assert(city>forest&&w.SpawnHeat(w.RouteX(-700),-700,true)>w.SpawnHeat(w.RouteX(-700),-700),"Habitat/night heat ordering");var other=new ExpeditionWorld(w.Seed);MigrationChecks.Assert(w.SpawnHeat(430,-700)==other.SpawnHeat(430,-700),"Heatmap seed mismatch");
  var old=player.Position;ExpeditionSupplies(true);var cache=props.FirstOrDefault(p=>p.Kind==9);MigrationChecks.Assert(cache!=null,"World supplies missing");player.Position=cache.Position;int food=game.Life.Food,amount=game.Craft.Materials[cache.Material];SearchSupply();MigrationChecks.Assert(game.Craft.Gathered.Contains(cache.Id)&&game.Life.Food==food+1&&game.Craft.Materials[cache.Material]==amount+cache.Amount,"Supply contents/save");ExpeditionSupplies(true);MigrationChecks.Assert(!props.Any(p=>p.Id==cache.Id),"Supply respawned after claim");var loaded=new ExpeditionGame(game.PathName);MigrationChecks.Assert(loaded.Craft.Gathered.Contains(cache.Id),"Supply claim reload");
  ClearEnemies();Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);SpawnInfected();MigrationChecks.Assert(!infected.Any(e=>Species(e.Id)==""&&Distance(e.Body.Position,player.Position)<90),"Danger inside starting sanctuary");MigrationChecks.Assert(props.Any(p=>p.Id==$"suburb/{game.Save.Seed}/cache/0"),"Suburb supplies missing");MigrationChecks.Assert(props.Count(p=>p.Id.StartsWith($"first-day/{game.Save.Seed}/forage/"))>=3,"Starting materials missing");ClearEnemies();Teleport(old.X,old.Z);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);GD.Print($"PASS / habitats: SE/NW route, unchanged northern route, sanctuary, seeded forest/city/night heat, supply rewards/persistence, Briar Lane homes/materials; forest={forest:F2} city={city:F2}");}
 async void CaptureWorldPolish(){try{testing=true;CloseMenu();ClearEnemies();weaponRoot.Visible=false;game.World.Changes.Time=1050;camera.Fov=68;
  Teleport(ExpeditionWorld.SpawnX,ExpeditionWorld.SpawnZ);camera.GlobalPosition=Ground(ExpeditionWorld.SpawnX+4,ExpeditionWorld.SpawnZ+8)+Vector3.Up*1.65f;camera.LookAt(Ground(ExpeditionWorld.SpawnX+18,ExpeditionWorld.SpawnZ-14)+Vector3.Up*.8f);await ArtShot("world-polish-01-southeast-camp");
  Teleport(game.World.RouteX(-500),-500);camera.GlobalPosition=player.Position+Vector3.Up*1.65f;camera.LookAt(Ground(game.World.RouteX(-540),-540)+Vector3.Up*1.65f);SpawnInfected();await ArtShot("world-polish-02-woodland-trail");
  Teleport(game.World.RouteX(-1460),-1460);camera.Position=new(0,1.65f,0);camera.Rotation=new(-.04f,.14f,0);SpawnInfected();await ArtShot("world-polish-03-town");
  ShowMap();await ArtShot("world-polish-04-progression-map");var map=menu.FindChildren("*","ExpeditionMapCanvas",true,false).OfType<ExpeditionMapCanvas>().FirstOrDefault();if(map==null){foreach(Node n in menu.GetChildren())foreach(Node c in n.GetChildren())foreach(Node d in c.GetChildren())if(d is ExpeditionMapCanvas m)map=m;}if(map!=null){map.Heat=true;map.QueueRedraw();}await ArtShot("world-polish-05-spawn-heatmap");if(map!=null){map.NightHeat=true;map.QueueRedraw();}await ArtShot("world-polish-06-night-heatmap");CloseMenu();GD.Print("PASS / populated world GPU captures");GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
}

